<?php
declare(strict_types=1);if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../botapi.php';require_once __DIR__.'/../lib/PersianDate.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a){header('Location:login.php');exit;}$flash='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{$tracking=(string)($_POST['tracking']??'');$answer=trim((string)($_POST['answer']??''));if($tracking===''||$answer==='')throw new RuntimeException('پاسخ خالی است.');$q=$pdo->prepare('SELECT iduser FROM support_message WHERE Tracking=? LIMIT 1');$q->execute([$tracking]);$uid=(string)$q->fetchColumn();if($uid==='')throw new RuntimeException('تیکت پیدا نشد.');$pdo->prepare("UPDATE support_message SET result=?,status='Answered' WHERE Tracking=?")->execute([$answer,$tracking]);sendmessage($uid,"🎟 <b>پاسخ پشتیبانی</b>\n\n".htmlspecialchars($answer,ENT_QUOTES,'UTF-8')."\n\nکد پیگیری: <code>".htmlspecialchars($tracking)."</code>",null,'HTML');$flash='پاسخ ثبت و ارسال شد.';}catch(Throwable$e){$flash=redfox_public_exception($e, 'panel/support_inbox.php');}}
$rows=[];try{$rows=$pdo->query("SELECT * FROM support_message ORDER BY (status='Unseen') DESC,time DESC LIMIT 500")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$flash='خطا در بارگذاری پیام‌ها: '.redfox_public_exception($e, 'panel/support_inbox.php');}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>صندوق پشتیبانی</title><link rel="stylesheet" href="css/theme.css"></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">صندوق پیام‌های پشتیبانی</h1><div class="page-head__sub">پیام‌های جدید کاربران با وضعیت خوانده‌نشده در ابتدای فهرست قرار دارند.</div></div><?php if($flash):?><div class="card"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="card"><div class="table-wrap"><table class="app-table"><tr><th>وضعیت</th><th>پیگیری</th><th>کاربر</th><th>دپارتمان</th><th>متن</th><th>زمان</th><th>پاسخ</th></tr><?php foreach($rows as$r):?><tr style="<?=$r['status']==='Unseen'?'font-weight:700':''?>"><td><?=$r['status']==='Unseen'?'🔴 جدید':'پاسخ داده‌شده'?></td><td><code><?=htmlspecialchars($r['Tracking'])?></code></td><td><?=htmlspecialchars($r['iduser'])?></td><td><?=htmlspecialchars($r['name_departman'])?></td><td><?=nl2br(htmlspecialchars(mb_substr((string)$r['text'],0,500)))?></td><td><?=htmlspecialchars($r['time'])?></td><td><?php if($r['status']==='Unseen'):?><form method="post"><input type="hidden" name="tracking" value="<?=htmlspecialchars($r['Tracking'])?>"><textarea name="answer" required placeholder="پاسخ ادمین"></textarea><button class="btn btn-primary">ارسال پاسخ</button></form><?php else:?><?=htmlspecialchars($r['result']??'')?><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
